class Solution:
    def isBalanced(self, num: str) -> bool:
        # Convert each character to an integer and compute sums for even and odd indices.
        # Note: Python uses 0-based indexing, so "even indices" correspond to index % 2 == 0
        # and "odd indices" correspond to index % 2 == 1.

        even_sum = 0
        odd_sum = 0

        for i, char in enumerate(num):
            digit = int(char)
            if i % 2 == 0:
                even_sum += digit
            else:
                odd_sum += digit

        return even_sum == odd_sum

