class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])

        # Create a DP table initialized to infinity
        dp = [[float('inf')] * m for _ in range(n)]
        dp[0][0] = 0

        # Fill the DP table
        for r in range(n):
            for c in range(m):
                if r == 0 and c == 0:
                    continue

                # Find the minimum time to reach one of the previous cells (top or left)
                prev_min = float('inf')
                if r > 0:
                    prev_min = min(prev_min, dp[r-1][c])
                if c > 0:
                    prev_min = min(prev_min, dp[r][c-1])

                # The time to move to (r, c) is max(prev_min, moveTime[r][c]) + 1
                # Because we can wait until moveTime[r][c] if needed, then take 1 second to move.
                dp[r][c] = max(prev_min, moveTime[r][c]) + 1

        return dp[n-1][m-1]

