class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])

        # dp[r][c] stores the minimum time to reach room (r, c)
        dp = [[float('inf')] * m for _ in range(n)]
        dp[0][0] = 0

        for r in range(n):
            for c in range(m):
                if r == 0 and c == 0:
                    continue
                # Get the minimum arrival time from previous cells (top or left)
                prev_min = float('inf')
                if r > 0:
                    prev_min = min(prev_min, dp[r-1][c])
                if c > 0:
                    prev_min = min(prev_min, dp[r][c-1])

                # If reachable from previous cells, calculate arrival time at current cell
                if prev_min != float('inf'):
                    # We can start moving into current room at time >= moveTime[r][c]
                    # The previous cell was reached at prev_min, so we can depart at max(prev_min, moveTime[r][c])
                    # Moving takes 1 second, so we arrive at (max(prev_min, moveTime[r][c])) + 1
                    dp[r][c] = max(prev_min, moveTime[r][c]) + 1

        return dp[n-1][m-1]

