class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        def simulate(start_idx, direction, nums_copy):
            curr = start_idx
            while True:
                if curr < 0 or curr >= n:
                    break

                val = nums_copy[curr]

                if val == 0:
                    if direction == -1:
                        curr -= 1
                    else:
                        curr += 1
                else:
                    nums_copy[curr] -= 1
                    if direction == -1:
                        direction = 1
                    else:
                        direction = -1

                    if direction == -1:
                        curr -= 1
                    else:
                        curr += 1
            return all(x == 0 for x in nums_copy)

        for i in range(n):
            if nums[i] == 0:
                # Left
                temp = nums[:]
                if simulate(i, -1, temp):
                    count += 1
                # Right
                temp = nums[:]
                if simulate(i, 1, temp):
                    count += 1

        return count

