class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)

        for l, r in queries:
            diff[l] += 1
            diff[r + 1] -= 1

        current_count = 0
        for i in range(n):
            current_count += diff[i]
            if current_count < nums[i]:
                return False

        return True

class Solution:
    def possibleStringCount(self, word: str) -> int:
        # Count total frequency of each character
        freq = {}
        for char in word:
            freq[char] = freq.get(char, 0) + 1

        # Initialize count with 1 (the case where no error occurred)
        count = 1

        # Find maximal contiguous segments of identical characters
        n = len(word)
        i = 0
        while i < n:
            j = i
            # Extend j while characters are the same
            while j < n and word[j] == word[i]:
                j += 1
            # Segment from i to j-1, length = j - i
            length = j - i
            if length > 1:
                # Check if this character appears only in this segment
                # If the total frequency equals the segment length, then this segment is isolated
                # and can be explained by exactly one error event.
                if freq[word[i]] == length:
                    count += (length - 1)
            i = j

        return count

