class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[j] will store the maximum points after processing the previous day ending at city j
        dp = [0] * n

        # Iterate through each day from 0 to k-1
        for i in range(k):
            new_dp = [0] * n
            for curr in range(n):
                # Option 1: Stay in 'curr' during day i
                stay_val = dp[curr] + stayScore[i][curr]

                # Option 2: Move from any city 'prev' to 'curr' during day i
                # Note: travelScore[prev][curr] is the points earned when moving from prev to curr
                travel_val = 0
                for prev in range(n):
                    val = dp[prev] + travelScore[prev][curr]
                    if val > travel_val:
                        travel_val = val

                new_dp[curr] = max(stay_val, travel_val)

            dp = new_dp

        return max(dp)

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        remainder_map = {}  # maps remainder -> prefix_sum at that index (earliest occurrence)
        max_val = float('-inf')

        for i in range(1, n + 1):
            rem = i % k

            if rem == 0:
                if prefix_sum[i] > max_val:
                    max_val = prefix_sum[i]
                remainder_map[rem] = prefix_sum[i]
            elif rem in remainder_map:
                prev_prefix = remainder_map[rem]
                current_sum = prefix_sum[i] - prev_prefix
                if current_sum > max_val:
                    max_val = current_sum
            else:
                remainder_map[rem] = prefix_sum[i]

        return max_val

