class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = {0: 0}
        current_prefix = 0
        max_val = -math.inf

        for i in range(len(nums)):
            current_prefix += nums[i]
            rem = (i + 1) % k
            if rem in min_prefix:
                candidate = current_prefix - min_prefix[rem]
                if candidate > max_val:
                    max_val = candidate
            if rem not in min_prefix or current_prefix < min_prefix[rem]:
                min_prefix[rem] = current_prefix

        return max_val

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 0

        # Since the constraints are small (nums.length <= 100), we can iterate over all subarrays.
        for i in range(n):
            current_prod = 1
            current_gcd = nums[i]
            current_lcm = nums[i]

            for j in range(i, n):
                num = nums[j]

                # Update GCD of the current subarray
                current_gcd = gcd(current_gcd, num)

                # Update LCM of the current subarray
                current_lcm = lcm(current_lcm, num)

                # Update product (watch out for potential overflow, but Python handles large integers automatically)
                current_prod *= num

                # Check if the condition holds: prod == gcd * lcm
                if current_prod == current_gcd * current_lcm:
                    max_len = max(max_len, j - i + 1)

        return max_len

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 0

        # Primes to consider: 2, 3, 5, 7 (since nums[i] <= 10)
        primes = [2, 3, 5, 7]

        # Precompute the exponent of each prime for each number
        # exponents[i][prime] = exponent of prime in nums[i]
        exponents = []
        for num in nums:
            e = {}
            for p in primes:
                cnt = 0
                temp = num
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                e[p] = cnt
            exponents.append(e)

        # Iterate over all subarrays
        for i in range(n):
            for j in range(i, n):
                # Check validity of subarray nums[i:j+1]
                valid_subarray = True
                for p in primes:
                    # Get valuations for each number in the subarray
                    vals = [exponents[k][p] for k in range(i, j+1)]
                    min_v = min(vals)
                    max_v = max(vals)
                    sum_v = sum(vals)

                    if sum_v != min_v + max_v:
                        valid_subarray = False
                        break

                if valid_subarray:
                    max_len = max(max_len, j - i + 1)

        return max_len

class Solution:
    def calculateScore(self, s: str) -> int:
        n = len(s)
        # Array to keep track of marked indices. -1 means unmarked.
        marked = [-1] * n

        # Dictionary for mirror mapping: 'a'->'z', 'b'->'y', etc.
        mirror_map = {chr(ord('a') + i): chr(ord('z') - i) for i in range(26)}

        total_score = 0

        for i in range(n):
            target_char = mirror_map[s[i]]

            # Find the closest unmarked index j < i such that s[j] == target_char
            j = -1
            # We can iterate backwards from i-1 down to 0
            # Since we want the closest (largest j < i), we stop at the first match
            for k in range(i - 1, -1, -1):
                if marked[k] != -1:
                    continue
                if s[k] == target_char:
                    j = k
                    break

            if j != -1:
                # Mark both indices
                marked[i] = 1
                marked[j] = 1
                total_score += (i - j)

        return total_score
